// biome-ignore-all lint/performance/noJsxPropsBind: Palette controls update the current controlled value.
"use client";

import type { AvatarPalette } from "@blobz/avatar-core";
import type { ChangeEvent, CSSProperties, MouseEvent } from "react";
import "./avatar-builder.css";

export const AVATAR_PALETTE_PRESETS = [
	{ name: "Sky", palette: ["#eef9ff", "#38bdf8"] },
	{ name: "Mango", palette: ["#fff7ed", "#fb923c"] },
	{ name: "Fern", palette: ["#f0fdf4", "#4ade80"] },
	{ name: "Plum", palette: ["#faf5ff", "#c084fc"] },
	{ name: "Coral", palette: ["#fff1f2", "#fb7185"] },
	{ name: "Lake", palette: ["#ecfeff", "#22d3ee"] },
	{ name: "Lemon", palette: ["#fffbeb", "#fbbf24"] },
	{ name: "Indigo", palette: ["#eef2ff", "#818cf8"] },
	{ name: "Peach", palette: ["#fff7ed", "#fd8a6a"] },
	{ name: "Mint", palette: ["#ecfdf5", "#34d399"] },
	{ name: "Berry", palette: ["#fdf2f8", "#e879b7"] },
	{ name: "Violet", palette: ["#f5f3ff", "#a78bfa"] },
	{ name: "Grape", palette: ["#f2f1f4", "#7c6cf2"] },
	{ name: "Bubblegum", palette: ["#fff0f6", "#f52b96"] },
	{ name: "Citrus", palette: ["#fff6e8", "#ff8a00"] },
	{ name: "Cocoa", palette: ["#f7f1eb", "#a06d3d"] },
] as const satisfies ReadonlyArray<{
	readonly name: string;
	readonly palette: AvatarPalette;
}>;

export interface AvatarPalettePickerProps {
	readonly className?: string;
	readonly idPrefix: string;
	readonly onPaletteChange: (palette: AvatarPalette) => void;
	readonly palette: AvatarPalette;
}

export function AvatarPalettePicker({
	className,
	idPrefix,
	onPaletteChange,
	palette,
}: AvatarPalettePickerProps) {
	const handleBackgroundChange = (event: ChangeEvent<HTMLInputElement>) => {
		onPaletteChange([event.currentTarget.value, palette[1]]);
	};
	const handleBodyChange = (event: ChangeEvent<HTMLInputElement>) => {
		onPaletteChange([palette[0], event.currentTarget.value]);
	};
	const handlePaletteChange = (event: MouseEvent<HTMLButtonElement>) => {
		const preset = AVATAR_PALETTE_PRESETS.find(
			(candidate) => candidate.name === event.currentTarget.value
		);
		if (preset) {
			onPaletteChange(preset.palette);
		}
	};

	return (
		<fieldset
			className={`blobz-builder__palette blobz-palette-picker${className ? ` ${className}` : ""}`}
		>
			<legend className="blobz-builder__visually-hidden">Avatar palette</legend>
			<div className="blobz-builder__palette-row">
				<span className="blobz-builder__palette-label">Palette</span>
				<div className="blobz-builder__palette-presets">
					{AVATAR_PALETTE_PRESETS.map((preset) => {
						const isSelected =
							palette[0] === preset.palette[0] &&
							palette[1] === preset.palette[1];

						return (
							<button
								aria-label={`Use ${preset.name} palette`}
								aria-pressed={isSelected}
								className="blobz-builder__palette-preset"
								key={preset.name}
								onClick={handlePaletteChange}
								type="button"
								value={preset.name}
							>
								<span
									aria-hidden="true"
									className="blobz-builder__swatches"
									style={
										{
											"--blobz-palette-background": preset.palette[0],
											"--blobz-palette-body": preset.palette[1],
										} as CSSProperties
									}
								/>
							</button>
						);
					})}
				</div>
				<span aria-hidden="true" className="blobz-builder__palette-divider" />
				<span className="blobz-builder__palette-label">Custom</span>
				<div className="blobz-builder__custom-colours">
					<label htmlFor={`${idPrefix}-background`}>
						<span className="blobz-builder__visually-hidden">
							Custom background colour
						</span>
						<input
							id={`${idPrefix}-background`}
							onChange={handleBackgroundChange}
							type="color"
							value={palette[0]}
						/>
					</label>
					<label htmlFor={`${idPrefix}-body`}>
						<span className="blobz-builder__visually-hidden">
							Custom body colour
						</span>
						<input
							id={`${idPrefix}-body`}
							onChange={handleBodyChange}
							type="color"
							value={palette[1]}
						/>
					</label>
				</div>
			</div>
		</fieldset>
	);
}

.blobz-builder,
.blobz-palette-picker {
	--blobz-builder-accent: #3b3a8f;
	--blobz-builder-background: #f4f3f8;
	--blobz-builder-border: #dddbe8;
	--blobz-builder-foreground: #1b1a26;
	--blobz-builder-muted: #6b6a7b;
	--blobz-builder-surface: #ffffff;
	display: grid;
	gap: 1.5rem;
	min-width: 0;
	font-family:
		system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
	color: var(--blobz-builder-foreground);
}

.blobz-builder *,
.blobz-builder *::before,
.blobz-builder *::after {
	box-sizing: border-box;
}

.blobz-builder button,
.blobz-builder input,
.blobz-builder select {
	font: inherit;
}

.blobz-builder button,
.blobz-builder input,
.blobz-builder select {
	accent-color: var(--blobz-builder-accent);
}

.blobz-builder button:focus-visible,
.blobz-builder input:focus-visible,
.blobz-builder select:focus-visible {
	outline: 2px solid var(--blobz-builder-accent);
	outline-offset: 2px;
}

.blobz-builder__studio {
	display: grid;
	grid-template-columns: minmax(14rem, 18rem) minmax(0, 1fr);
	gap: 2rem;
	align-items: start;
}

.blobz-builder__preview-rail {
	position: sticky;
	top: 6.75rem;
	display: grid;
	gap: 0.75rem;
}

.blobz-builder__preview {
	width: 100%;
	aspect-ratio: 1;
	overflow: hidden;
	background: var(--blobz-builder-background);
	border: 1px solid var(--blobz-builder-border);
	border-radius: 1rem;
}

.blobz-builder__preview img {
	display: block;
}

.blobz-builder__preview-actions,
.blobz-builder__controls,
.blobz-builder__primary-controls,
.blobz-builder__custom-controls,
.blobz-builder__appearance {
	display: grid;
	gap: 1.25rem;
	min-width: 0;
}

.blobz-builder__controls {
	gap: 1.75rem;
}

.blobz-builder__preview-actions {
	gap: 0.5rem;
}

.blobz-builder__mode-switch {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 0.375rem;
}

.blobz-builder__mode-switch legend {
	grid-column: 1 / -1;
}

.blobz-builder__mode-switch button,
.blobz-builder__custom-actions button {
	display: inline-flex;
	gap: 0.45rem;
	align-items: center;
	justify-content: center;
	min-height: 2.65rem;
	padding: 0.6rem 0.8rem;
	color: var(--blobz-builder-foreground);
	cursor: pointer;
	background: var(--blobz-builder-surface);
	border: 1px solid var(--blobz-builder-border);
	border-radius: 0.65rem;
	transition:
		color 150ms ease,
		background-color 150ms ease,
		border-color 150ms ease,
		transform 150ms ease;
}

.blobz-builder__custom-actions svg {
	width: 1rem;
	height: 1rem;
}

.blobz-builder__mode-switch button[aria-pressed="true"] {
	color: var(--blobz-builder-surface);
	background: var(--blobz-builder-foreground);
	border-color: var(--blobz-builder-foreground);
}

.blobz-builder fieldset {
	min-width: 0;
	padding: 0;
	margin: 0;
	border: 0;
}

.blobz-builder legend,
.blobz-builder__generated-controls > label {
	display: block;
	margin-bottom: 0.6rem;
	font-size: 0.75rem;
	font-weight: 700;
	color: var(--blobz-builder-muted);
	text-transform: uppercase;
	letter-spacing: 0.06em;
}

.blobz-builder__frame-options {
	display: flex;
	flex-wrap: wrap;
	gap: 0.4rem;
}

.blobz-builder__frame-options legend {
	flex-basis: 100%;
}

.blobz-builder__frame-options label {
	position: relative;
	cursor: pointer;
}

.blobz-builder__frame-options input {
	position: absolute;
	width: 1px;
	height: 1px;
	opacity: 0;
}

.blobz-builder__frame-options span {
	display: block;
	padding: 0.45rem 0.8rem;
	text-transform: capitalize;
	border: 1px solid var(--blobz-builder-border);
	border-radius: 999px;
}

.blobz-builder__frame-options input:checked + span {
	color: var(--blobz-builder-surface);
	background: var(--blobz-builder-foreground);
	border-color: var(--blobz-builder-foreground);
}

.blobz-builder__frame-options input:focus-visible + span {
	outline: 2px solid var(--blobz-builder-accent);
	outline-offset: 2px;
}

.blobz-builder__palette {
	min-width: 0;
}

.blobz-palette-picker {
	padding: 0;
	border: 0;
}

.blobz-palette-picker button:focus-visible,
.blobz-palette-picker input:focus-visible {
	outline: 2px solid var(--blobz-builder-accent);
	outline-offset: 2px;
}

.blobz-builder__visually-hidden {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	white-space: nowrap;
	border: 0;
	clip: rect(0, 0, 0, 0);
}

.blobz-builder__palette-row {
	display: grid;
	grid-template-columns: auto minmax(0, 1fr) auto auto auto;
	gap: 0.55rem;
	align-items: start;
}

.blobz-builder__palette-label {
	margin-top: 0.85rem;
	font-size: 0.75rem;
	font-weight: 700;
	color: var(--blobz-builder-muted);
	letter-spacing: 0.01em;
}

.blobz-builder__palette-presets {
	display: flex;
	flex-wrap: wrap;
	gap: 0.45rem;
}

.blobz-builder__palette-preset {
	width: 2.75rem;
	height: 2.75rem;
	padding: 0.2rem;
	cursor: pointer;
	background: var(--blobz-builder-surface);
	border: 1px solid var(--blobz-builder-border);
	border-radius: 50%;
	transition:
		border-color 150ms ease,
		box-shadow 150ms ease,
		transform 150ms ease;
}

.blobz-builder__palette-preset[aria-pressed="true"] {
	padding: 0.15rem;
	border: 2px solid var(--blobz-builder-accent);
	box-shadow: 0 0 0 2px var(--blobz-builder-surface);
}

.blobz-builder__swatches {
	position: relative;
	display: block;
	width: 100%;
	height: 100%;
	overflow: hidden;
	background: var(--blobz-builder-surface);
	border-radius: 50%;
}

.blobz-builder__swatches::before,
.blobz-builder__swatches::after {
	position: absolute;
	inset: 0;
	content: "";
}

.blobz-builder__swatches::before {
	background: var(--blobz-palette-background);
	clip-path: polygon(0 0, 100% 0, 0 100%);
}

.blobz-builder__swatches::after {
	background: var(--blobz-palette-body);
	clip-path: polygon(100% 0, 100% 100%, 0 100%);
}

.blobz-builder__palette-divider {
	width: 1px;
	height: 2rem;
	margin: 0.4rem 0.25rem 0;
	background: var(--blobz-builder-border);
}

.blobz-builder__custom-colours {
	display: flex;
	gap: 0.45rem;
}

.blobz-builder__custom-colours label {
	display: block;
}

.blobz-builder__custom-colours input[type="color"] {
	width: 2.75rem;
	height: 2.75rem;
	padding: 0.18rem;
	cursor: pointer;
	background: var(--blobz-builder-surface);
	border: 1px solid var(--blobz-builder-border);
	border-radius: 50%;
}

.blobz-builder__custom-colours
	input[type="color"]::-webkit-color-swatch-wrapper {
	padding: 0.08rem;
}

.blobz-builder__custom-colours input[type="color"]::-webkit-color-swatch {
	border: 0;
	border-radius: 50%;
}

.blobz-builder__custom-colours input[type="color"]::-moz-color-swatch {
	border: 0;
	border-radius: 50%;
}

.blobz-builder__generated-controls input {
	width: 100%;
	min-height: 2.75rem;
	padding: 0.65rem 0.75rem;
	color: var(--blobz-builder-foreground);
	background: var(--blobz-builder-surface);
	border: 1px solid var(--blobz-builder-border);
	border-radius: 0.65rem;
}

.blobz-builder__generated-controls p {
	margin: 0.45rem 0 0;
	font-size: 0.82rem;
	color: var(--blobz-builder-muted);
}

.blobz-builder__custom-actions {
	display: flex;
	flex-wrap: wrap;
	gap: 0.5rem;
}

.blobz-builder__custom-controls > fieldset {
	padding-top: 1.25rem;
	border-top: 1px solid var(--blobz-builder-border);
}

.blobz-builder__choice-group {
	display: grid;
	gap: 0.7rem;
}

.blobz-builder__choice-grid {
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(5rem, 1fr));
	gap: 0.55rem;
}

.blobz-builder__choice {
	display: grid;
	gap: 0.3rem;
	align-items: center;
	justify-items: center;
	min-width: 0;
	padding: 0.45rem;
	font-size: 0.75rem;
	color: var(--blobz-builder-foreground);
	overflow-wrap: anywhere;
	cursor: pointer;
	background: var(--blobz-builder-surface);
	border: 1px solid var(--blobz-builder-border);
	border-radius: 0.75rem;
	transition:
		background-color 150ms ease,
		border-color 150ms ease,
		transform 150ms ease;
}

.blobz-builder__choice[aria-pressed="true"] {
	padding: calc(0.45rem - 1px);
	border: 2px solid var(--blobz-builder-accent);
}

.blobz-builder__choice img {
	display: block;
	max-width: 100%;
}

.blobz-builder__details {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 1rem;
}

.blobz-builder__details legend {
	grid-column: 1 / -1;
}

.blobz-builder__details > label:not(.blobz-builder__checkbox) {
	display: grid;
	gap: 0.4rem;
	font-size: 0.85rem;
	font-weight: 600;
}

.blobz-builder__details select {
	min-height: 2.5rem;
	padding: 0.45rem 0.6rem;
	color: var(--blobz-builder-foreground);
	background: var(--blobz-builder-surface);
	border: 1px solid var(--blobz-builder-border);
	border-radius: 0.55rem;
}

.blobz-builder__checkbox {
	display: flex;
	grid-column: 1 / -1;
	gap: 0.5rem;
	align-items: center;
	font-size: 0.875rem;
}

.blobz-builder__checkbox input {
	width: 1.1rem;
	height: 1.1rem;
}

.blobz-builder__range {
	display: grid;
	grid-template-columns: minmax(7rem, 1fr) minmax(7rem, 2fr) 3rem;
	align-items: center;
}

.blobz-builder__range input {
	width: 100%;
	min-width: 0;
}

.blobz-builder__range output {
	font-variant-numeric: tabular-nums;
	color: var(--blobz-builder-muted);
	text-align: right;
}

@media (hover: hover) and (pointer: fine) {
	.blobz-builder__mode-switch button:hover,
	.blobz-builder__custom-actions button:hover,
	.blobz-builder__choice:not([aria-pressed="true"]):hover,
	.blobz-builder__palette-preset:not([aria-pressed="true"]):hover {
		border-color: var(--blobz-builder-muted);
	}

	.blobz-builder__choice:hover,
	.blobz-builder__palette-preset:hover {
		background: color-mix(
			in srgb,
			var(--blobz-builder-surface) 88%,
			var(--blobz-builder-background)
		);
	}
}

.blobz-builder__mode-switch button:active,
.blobz-builder__custom-actions button:active,
.blobz-builder__choice:active,
.blobz-builder__palette-preset:active {
	transform: scale(0.97);
}

@media (max-width: 56rem) {
	.blobz-builder__studio {
		grid-template-columns: minmax(0, 1fr);
	}

	.blobz-builder__preview-rail {
		position: static;
		grid-template-columns: minmax(12rem, 16rem) minmax(0, 1fr);
		align-items: start;
	}
}

@media (max-width: 40rem) {
	.blobz-builder__preview-rail,
	.blobz-builder__details {
		grid-template-columns: minmax(0, 1fr);
	}

	.blobz-builder__preview {
		max-width: 13rem;
	}

	.blobz-builder__details legend,
	.blobz-builder__checkbox {
		grid-column: auto;
	}

	.blobz-builder__range {
		grid-template-columns: minmax(6.5rem, 1fr) minmax(5rem, 1.5fr) 2.5rem;
	}

	.blobz-builder__palette-row {
		grid-template-columns: auto minmax(0, 1fr);
	}

	.blobz-builder__palette-divider {
		display: none;
	}
}

@media (prefers-reduced-motion: reduce) {
	.blobz-builder__mode-switch button,
	.blobz-builder__custom-actions button,
	.blobz-builder__choice,
	.blobz-builder__palette-preset {
		transition: none;
	}

	.blobz-builder__mode-switch button:active,
	.blobz-builder__custom-actions button:active,
	.blobz-builder__choice:active,
	.blobz-builder__palette-preset:active {
		transform: none;
	}
}

@media (prefers-color-scheme: dark) {
	.blobz-builder,
	.blobz-palette-picker {
		--blobz-builder-accent: #aaa8ff;
		--blobz-builder-background: #15141d;
		--blobz-builder-border: #343242;
		--blobz-builder-foreground: #f1f0f7;
		--blobz-builder-muted: #aaa8b8;
		--blobz-builder-surface: #201f2a;
	}
}
